INSERT OR IGNORE INTO "report_jobs" ("id","report_id","station_key","kind","status","report_version","input","plan","questions","error","proposal_id","created_at","updated_at","actor") VALUES ('a0ba83df-294f-4c67-afd2-6843dae31503','e631cdd7-ba40-4a8a-8e57-e20e1115071d','S202103','structure','needs_info','2026-10-05T15:19:24.763Z','{"kind":"structure","notes":"1. 대략 추정해서 처리\n2. 상단 간판과 받침까지 포함되는거 맞고, 좌우 배너는 만들필요없고 뒤쪽 목재벽은 이미 존재하는 기둥벽이므로 제외함. 사용의 위치를 안내하는 바닥면에 발바닥 표기 시트지 안내는 반영해야함","alias":null,"structure":null,"permitted_ids":[],"engine":"dots"}',NULL,'["추정 처리와 키오스크 포함·제외 범위는 확인했습니다. 다만 현재 구조물 형상 값은 비어 있고 연결 도구에는 치수·정면 방향을 입력하는 기능이 없습니다. Toolkit 승인자 화면에서 ‘추정’으로 구조물 형상을 설정해 주실 수 있나요? 사진에는 절대 크기의 기준이 없어 숫자를 근거 있게 산출하기 어렵습니다.","바닥 발바닥 안내 시트지도 사진에서 확인했습니다. 현재 반환 형식은 front/left/right/back만 허용하고 수평 바닥면·데칼 항목이 없어 정확히 반영할 수 없습니다. 바닥 시트지를 수평면으로 반영할 수 있는 작업 또는 입력 항목을 Toolkit에서 제공해 주실 수 있나요?"]',NULL,NULL,'2026-10-05T15:19:24.763Z','2026-10-05T15:21:24.124Z','공개 재현용 운영자');
INSERT OR IGNORE INTO "report_jobs" ("id","report_id","station_key","kind","status","report_version","input","plan","questions","error","proposal_id","created_at","updated_at","actor") VALUES ('f8c65426-366d-4596-bd7e-d9b6b1876ce3','e631cdd7-ba40-4a8a-8e57-e20e1115071d','S202103','structure','needs_info','2026-10-05T15:11:03.833Z','{"kind":"structure","notes":"","alias":null,"structure":null,"permitted_ids":[],"engine":"dots"}',NULL,'["승인자 화면에 구조물 이름, 폭·깊이·높이(m), 정면 방향, 각 치수의 실측/추정 여부를 입력해 주시겠어요? 현재 승인된 구조물 형상 정보가 없어 사진만으로 크기나 방향을 확정할 수 없습니다.","대상이 사진 중앙의 ‘AI 역무원 / AI Guide’ 키오스크이며 상단 간판과 하단 받침까지 포함하는지 확인해 주세요. 좌우 안내 배너와 뒤쪽 목재 벽은 제외하는 범위가 맞나요? 현재 사진으로 확인되는 정면만 사용하고 보이지 않는 면은 만들지 않겠습니다."]',NULL,NULL,'2026-10-05T15:11:03.833Z','2026-10-05T15:15:04.028Z','공개 재현용 운영자');
INSERT OR IGNORE INTO "audit_log" ("id","action","target","detail","created_at","actor") VALUES ('50c15ded-fb42-41c0-8df9-a643034aeae1','dots.needs-info','a0ba83df-294f-4c67-afd2-6843dae31503','{"questions":["추정 처리와 키오스크 포함·제외 범위는 확인했습니다. 다만 현재 구조물 형상 값은 비어 있고 연결 도구에는 치수·정면 방향을 입력하는 기능이 없습니다. Toolkit 승인자 화면에서 ‘추정’으로 구조물 형상을 설정해 주실 수 있나요? 사진에는 절대 크기의 기준이 없어 숫자를 근거 있게 산출하기 어렵습니다.","바닥 발바닥 안내 시트지도 사진에서 확인했습니다. 현재 반환 형식은 front/left/right/back만 허용하고 수평 바닥면·데칼 항목이 없어 정확히 반영할 수 없습니다. 바닥 시트지를 수평면으로 반영할 수 있는 작업 또는 입력 항목을 Toolkit에서 제공해 주실 수 있나요?"]}','2026-10-05T15:21:24.124Z','공개 재현용 운영자');
